import { createHash } from "node:crypto";

const REPRODUCER_KINDS = new Set(["scenario", "route", "command-id"]);
const REPRODUCER_KEYS = Object.freeze({
  scenario: Object.freeze(["scenarioId", "fixtureId"]),
  route: Object.freeze(["routeId", "method", "path"]),
  "command-id": Object.freeze(["commandId"]),
});
const FORBIDDEN_KEY = /(?:raw[_-]?prompt|messages?|body|authorization|api[_-]?key|headers?|secret|token|password|credential|private[_-]?key)/i;
const FORBIDDEN_VALUE = /(?:\bsk-[A-Za-z0-9_-]{8,}|\bphc_[A-Za-z0-9_-]{8,}|\bghp_[A-Za-z0-9]{8,}|\bAKIA[0-9A-Z]{16}\b|BEGIN(?: [A-Z]+)? PRIVATE KEY\b|-----BEGIN [A-Z ]*PRIVATE KEY-----|\bBearer\s+[A-Za-z0-9._~+/=-]{8,})/i;
const MAX_REPRODUCER_LENGTH = 4096;
const MAX_STRING_LENGTH = 8192;

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function assertSafeString(value, location) {
  if (typeof value !== "string") throw new TypeError(`${location} must be a string`);
  if (value.length > MAX_STRING_LENGTH) throw new RangeError(`${location} exceeds the supported bound`);
  if (FORBIDDEN_VALUE.test(value)) throw new Error(`${location} contains a credential-like value`);
  return value;
}

/**
 * Recursively checks the complete trace. This deliberately treats a forbidden key
 * anywhere as a reason to reject the entire trace; there is no partial output.
 */
function assertDesensitized(value, location = "trace", seen = new WeakSet()) {
  if (typeof value === "string") {
    assertSafeString(value, location);
    return;
  }
  if (value === null || typeof value === "boolean" || typeof value === "number") return;
  if (typeof value === "undefined") return;
  if (!isPlainObject(value) && !Array.isArray(value)) {
    throw new TypeError(`${location} contains an unsupported value`);
  }
  if (seen.has(value)) throw new Error(`${location} contains a cycle`);
  seen.add(value);
  if (Array.isArray(value)) {
    value.forEach((entry, index) => assertDesensitized(entry, `${location}[${index}]`, seen));
  } else {
    for (const [key, entry] of Object.entries(value)) {
      if (FORBIDDEN_KEY.test(key)) throw new Error(`${location}.${key} is not desensitized`);
      assertDesensitized(entry, `${location}.${key}`, seen);
    }
  }
  seen.delete(value);
}

function canonicalJson(value) {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(",")}}`;
}

function digest(value) {
  return `sha256:${createHash("sha256").update(canonicalJson(value), "utf8").digest("hex")}`;
}

function outcomeOf(trace) {
  const outcome = String(trace.outcome ?? trace.status ?? trace.result ?? "").toLowerCase();
  if (["failed", "fail", "error", "failure"].includes(outcome)) return "failure";
  if (["succeeded", "success", "passed", "pass", "completed", "complete"].includes(outcome)) return "success";
  if (["rejected", "reject", "denied", "deny"].includes(outcome)) return "rejected";
  if (["cancelled", "canceled", "cancel", "aborted"].includes(outcome)) return "cancelled";
  throw new Error(`unsupported trace outcome: ${outcome || "missing"}`);
}

function normalizeReproducer(reproducer) {
  if (!isPlainObject(reproducer)) throw new TypeError("trace.reproducer must be an object");
  const kind = reproducer.kind;
  if (!REPRODUCER_KINDS.has(kind)) throw new Error("reproducer.kind must be scenario, route, or command-id");
  if (kind === "route" && (typeof reproducer.method !== "string" || typeof reproducer.path !== "string")) {
    throw new Error("route reproducer requires method and path");
  }
  const allowed = new Set(REPRODUCER_KEYS[kind]);
  for (const [key, value] of Object.entries(reproducer)) {
    if (!allowed.has(key)) throw new Error(`unsupported ${kind} reproducer field: ${key}`);
    assertSafeString(value, `reproducer.${key}`);
  }
  if (kind === "scenario" && !reproducer.scenarioId && !reproducer.fixtureId) {
    throw new Error("scenario reproducer requires scenarioId or fixtureId");
  }
  if (kind === "route" && !reproducer.routeId) {
    throw new Error("route reproducer requires routeId");
  }
  if (kind === "command-id" && !reproducer.commandId) {
    throw new Error("command-id reproducer requires commandId");
  }
  const encoded = canonicalJson(reproducer);
  if (encoded.length > MAX_REPRODUCER_LENGTH) throw new RangeError("reproducer exceeds the supported bound");
  return Object.fromEntries(Object.entries(reproducer).sort(([a], [b]) => a.localeCompare(b)));
}

function normalizeSelector(trace) {
  const source = trace.selector ?? {};
  if (!isPlainObject(source)) throw new TypeError("trace.selector must be an object");
  const runId = source.runId ?? trace.runId;
  const attempt = source.attempt ?? trace.attempt;
  if (typeof runId !== "string" || !runId.trim()) throw new Error("selector.runId is required");
  if (!Number.isSafeInteger(attempt) || attempt < 0) throw new Error("selector.attempt must be a non-negative integer");
  assertSafeString(runId, "selector.runId");
  return { runId, attempt };
}

function redactedTraceMetadata(trace) {
  const metadata = {};
  for (const key of ["traceId", "createdAt", "durationMs", "suite", "testCase"]) {
    if (trace[key] !== undefined) metadata[key] = trace[key];
  }
  return metadata;
}

/**
 * Convert one already-desensitized trace into a deterministic eval sample.
 * The input trace is never mutated and remains the source of original evidence.
 */
export function traceToEvalSample(trace) {
  if (!isPlainObject(trace)) throw new TypeError("trace must be an object");
  assertDesensitized(trace);
  const outcome = outcomeOf(trace);
  const reproducer = normalizeReproducer(trace.reproducer);
  const selector = normalizeSelector(trace);
  const metadata = redactedTraceMetadata(trace);
  const base = {
    version: 1,
    outcome,
    reproducer,
    selector,
    metadata,
    expectations: outcome === "failure"
      ? { beforeFix: "fail", afterFix: "pass" }
      : { beforeFix: "pass", afterFix: "pass" },
  };
  return Object.freeze({ ...base, digest: digest(base) });
}

/**
 * Explicitly convert only the supplied traces. A rejected trace produces a
 * diagnostic and no sample; other traces continue to be converted.
 */
export function convertSelectedTraces(traces) {
  if (!Array.isArray(traces)) throw new TypeError("traces must be an array");
  const samples = [];
  const diagnostics = [];
  traces.forEach((trace, index) => {
    try {
      samples.push(traceToEvalSample(trace));
    } catch (error) {
      diagnostics.push({
        index,
        runId: isPlainObject(trace) ? trace.runId ?? trace.selector?.runId ?? null : null,
        attempt: isPlainObject(trace) ? trace.attempt ?? trace.selector?.attempt ?? null : null,
        code: "TRACE_REJECTED",
        reason: error instanceof Error ? error.message : String(error),
      });
    }
  });
  return Object.freeze({ samples: Object.freeze(samples), diagnostics: Object.freeze(diagnostics) });
}

export function assertTraceDesensitized(trace) {
  assertDesensitized(trace);
  return true;
}

export const isTraceDesensitized = (trace) => {
  try {
    assertDesensitized(trace);
    return true;
  } catch {
    return false;
  }
};

export const traceToEvalSampleAlias = traceToEvalSample;

export type ReproducerKind = "scenario" | "route" | "command-id";

export type Reproducer =
  | { kind: "scenario"; scenarioId?: string; fixtureId?: string }
  | { kind: "route"; routeId: string; method: string; path: string }
  | { kind: "command-id"; commandId: string };

export interface TraceSelector {
  runId: string;
  attempt: number;
}

export interface TraceOutcome {
  outcome?: "failed" | "fail" | "error" | "failure" | "succeeded" | "success" | "passed" | "pass" | "completed" | "complete" | "rejected" | "reject" | "denied" | "deny" | "cancelled" | "canceled" | "cancel" | "aborted";
  status?: TraceOutcome["outcome"];
  result?: TraceOutcome["outcome"];
  runId?: string;
  attempt?: number;
  selector?: TraceSelector;
  reproducer: Reproducer;
  traceId?: string;
  createdAt?: string;
  durationMs?: number;
  suite?: string;
  testCase?: string;
  [key: string]: unknown;
}

export interface EvalSample {
  readonly version: 1;
  readonly outcome: "failure" | "success" | "rejected" | "cancelled";
  readonly reproducer: Reproducer;
  readonly selector: TraceSelector;
  readonly metadata: Readonly<Record<string, unknown>>;
  readonly expectations: Readonly<{ beforeFix: "fail" | "pass"; afterFix: "pass" }>;
  readonly digest: string;
}

export interface ConversionDiagnostic {
  readonly index: number;
  readonly runId: string | null;
  readonly attempt: number | null;
  readonly code: "TRACE_REJECTED";
  readonly reason: string;
}

export interface ConversionResult {
  readonly samples: readonly EvalSample[];
  readonly diagnostics: readonly ConversionDiagnostic[];
}

export function traceToEvalSample(trace: TraceOutcome): EvalSample;

export function convertSelectedTraces(traces: readonly TraceOutcome[]): ConversionResult;

export function assertTraceDesensitized(trace: unknown): true;

export function isTraceDesensitized(trace: unknown): boolean;

export const traceToEvalSampleAlias: typeof traceToEvalSample;

